<script setup lang="ts">
import { computed, nextTick, onMounted, ref } from 'vue'
import { qtrc, useLanguage } from '../i18n'
import { DEFAULT_NEW_SCORE_PICKUP, DEFAULT_NEW_SCORE_TEMPO, KEY_ATONAL } from '../../src/index'
import type { ScoreInfo } from './instrumentmodels'
import ScoreInfoDropdown from './ScoreInfoDropdown.vue'
const props = defineProps<{ info: ScoreInfo }>()
const emit = defineEmits<{ (e: 'update:info', info: ScoreInfo): void }>()
useLanguage()
function patch(partial: Partial<ScoreInfo>) { emit('update:info', { ...props.info, ...partial }) }
const keys = [
  ['C major','A minor','',0], ['G major','E minor','',1], ['D major','B minor','',2], ['A major','F♯ minor','',3], ['E major','C♯ minor','',4], ['B major','G♯ minor','',5], ['F♯ major','D♯ minor','',6], ['C♯ major','A♯ minor','',7],
  ['Open/Atonal','Open/Atonal','',KEY_ATONAL], ['F major','D minor','',-1], ['B♭ major','G minor','',-2], ['E♭ major','C minor','',-3], ['A♭ major','F minor','',-4], ['D♭ major','B♭ minor','',-5], ['G♭ major','E♭ minor','',-6], ['C♭ major','A♭ minor','',-7],
] as const
const notes = [
  {duration:'16th',dot:false,label:'16th note'}, {duration:'16th',dot:true,label:'Dotted 16th note'}, {duration:'eighth',dot:false,label:'Eighth note'}, {duration:'eighth',dot:true,label:'Dotted eighth note'}, {duration:'quarter',dot:false,label:'Quarter note'}, {duration:'quarter',dot:true,label:'Dotted quarter note'}, {duration:'half',dot:false,label:'Half note'}, {duration:'half',dot:true,label:'Dotted half note'}, {duration:'whole',dot:false,label:'Whole note'},
] as const
const symbols = { whole:'', half:'', quarter:'', eighth:'', '16th':'' }
const denominators = [1,2,4,8,16,32,64,128]
const minor = ref(false)
const key = computed(() => keys.find(k => k[3] === props.info.key) ?? keys[0])
const keyName = computed(() => qtrc('project/newscore', key.value[minor.value ? 1 : 0]))
const lastTempo = ref({ ...(props.info.tempo ?? DEFAULT_NEW_SCORE_TEMPO) })
const lastPickup = ref({ ...(props.info.pickup ?? DEFAULT_NEW_SCORE_PICKUP) })
const fraction = ref(props.info.timesigType === 'normal' ? { ...props.info.timesig } : { numerator:4, denominator:4 })
const tempo = computed(() => props.info.tempo ?? lastTempo.value)
const pickup = computed(() => props.info.pickup ?? lastPickup.value)
const tempoIndex = computed(() => { const n = notes.findIndex(n => n.duration === tempo.value.duration && n.dot === tempo.value.dot); return n < 0 ? 4 : n })
const timeLabel = computed(() => props.info.timesigType === 'common' ? qtrc('engraving/timesig','Common time') : props.info.timesigType === 'cut' ? qtrc('engraving/timesig','Cut time') : `${props.info.timesig.numerator}/${props.info.timesig.denominator}`)
const measuresLabel = computed(() => `${qtrc('project/newscore', '%Ln measure(s),', '', props.info.measures)} ${props.info.pickup ? `${qtrc('project/newscore','pickup:')} ${props.info.pickup.numerator}/${props.info.pickup.denominator}` : qtrc('project/newscore','no pickup')}`)
const titleInput = ref<HTMLInputElement | null>(null)
onMounted(() => nextTick(() => titleInput.value?.focus()))
function clamp(value: string, min: number, max: number, fallback: number) { const n = Math.round(Number(value)); return Number.isFinite(n) && value.trim() !== '' ? Math.min(max, Math.max(min,n)) : fallback }
function setTime(type: ScoreInfo['timesigType'], f = fraction.value) { fraction.value = f; patch({timesigType:type, timesig:type === 'common' ? {numerator:4,denominator:4} : type === 'cut' ? {numerator:2,denominator:2} : f}) }
function setTempo(value: Partial<NonNullable<ScoreInfo['tempo']>>) { lastTempo.value = {...tempo.value,...value}; patch({tempo:lastTempo.value}) }
function setPickup(value: {numerator:number;denominator:number}) { lastPickup.value = value; patch({pickup:value}) }
function digits(n: number) { return String(n).replace(/\d/g, d => String.fromCharCode(''.charCodeAt(0)+Number(d))) }
</script>
<template>
  <div class="score-info"><h3>{{ qtrc('project/newscore','Additional score information') }}</h3>
    <div class="score-options" role="group" :aria-label="qtrc('project/newscore','Score options')">
      <ScoreInfoDropdown :label="qtrc('project/newscore','Key signature')" :value-label="keyName"><template #value><span class="icon-glyph big" aria-hidden="true">{{ key[2] }}</span><span class="value-text">{{ keyName }}</span></template><div class="segmented text" role="radiogroup"><button role="radio" :aria-checked="!minor" @click="minor=false">{{ qtrc('project/newscore','Major','key signature mode') }}</button><button role="radio" :aria-checked="minor" @click="minor=true">{{ qtrc('project/newscore','Minor','key signature mode') }}</button></div><div class="key-grid" role="radiogroup" :aria-label="qtrc('project/newscore','Key signature')"><button v-for="k in keys" :key="k[3]" role="radio" :aria-checked="k[3]===info.key" :title="qtrc('project/newscore',k[minor ? 1 : 0])" @click="patch({key:k[3]})"><span class="icon-glyph big" aria-hidden="true">{{ k[2] }}</span><span class="key-name">{{ qtrc('project/newscore',k[minor ? 1 : 0]) }}</span></button></div></ScoreInfoDropdown>
      <ScoreInfoDropdown :label="qtrc('project/newscore','Time signature')" :value-label="timeLabel"><template #value><svg class="timesig" :width="Math.max(String(info.timesig.numerator).length,String(info.timesig.denominator).length,1)*17.6" height="32" :viewBox="`0 0 ${Math.max(String(info.timesig.numerator).length,String(info.timesig.denominator).length,1)*17.6} 32`" aria-hidden="true"><text v-if="info.timesigType !== 'normal'" x="50%" y="16" font-size="32" text-anchor="middle">{{ info.timesigType === 'common' ? '' : '' }}</text><template v-else><text x="50%" y="8" font-size="32" text-anchor="middle">{{ digits(info.timesig.numerator) }}</text><text x="50%" y="24" font-size="32" text-anchor="middle">{{ digits(info.timesig.denominator) }}</text></template></svg></template><div class="radio-rows" role="radiogroup" :aria-label="qtrc('project/newscore','Time signature')"><label><input type="radio" name="timesig" :checked="info.timesigType==='normal'" @change="setTime('normal')" /><span class="fraction-input" role="group" :aria-label="qtrc('project/newscore','Time signature')"><input type="number" min="1" max="63" aria-label="Numerator" :value="fraction.numerator" @change="setTime('normal',{...fraction,numerator:clamp(($event.target as HTMLInputElement).value,1,63,fraction.numerator)})" /><span aria-hidden="true">/</span><select aria-label="Denominator" :value="fraction.denominator" @change="setTime('normal',{...fraction,denominator:Number(($event.target as HTMLSelectElement).value)})"><option v-for="d in denominators" :key="d">{{ d }}</option></select></span></label><label v-for="item in [{type:'common',symbol:'',label:'Common time'},{type:'cut',symbol:'',label:'Cut time'}] as const" :key="item.type"><input type="radio" name="timesig" :checked="info.timesigType===item.type" @change="setTime(item.type)" /><svg class="timesig" width="17.6" height="32" viewBox="0 0 17.6 32" aria-hidden="true"><text x="8.8" y="16" font-size="32" text-anchor="middle">{{ item.symbol }}</text></svg> {{ qtrc('engraving/timesig',item.label) }}</label></div></ScoreInfoDropdown>
      <ScoreInfoDropdown :label="qtrc('project/newscore','Tempo')" :value-label="info.tempo ? `${qtrc('project/newscore',notes[tempoIndex].label)} = ${tempo.bpm}` : qtrc('EditStaffBase','None')"><template #value><span v-if="info.tempo" class="tempo-value"><span class="smufl" aria-hidden="true">{{ symbols[tempo.duration] }}{{ tempo.dot ? ' ' : '' }}</span> = {{ tempo.bpm }}</span><span v-else class="value-text muted">{{ qtrc('EditStaffBase','None') }}</span></template><label class="check"><input type="checkbox" :checked="!!info.tempo" @change="patch({tempo:($event.target as HTMLInputElement).checked ? tempo : null})" />{{ qtrc('project/newscore','Show tempo marking on my score') }}</label><div class="tempo-row"><select aria-label="Note value" :disabled="!info.tempo" :value="tempoIndex" @change="e=>{const n=notes[Number((e.target as HTMLSelectElement).value)];setTempo({duration:n.duration,dot:n.dot})}"><option v-for="(n,i) in notes" :key="i" :value="i">{{ qtrc('project/newscore',n.label) }}</option></select><span aria-hidden="true">=</span><input type="number" min="20" max="400" aria-label="Beats per minute" :disabled="!info.tempo" :value="tempo.bpm" @change="setTempo({bpm:clamp(($event.target as HTMLInputElement).value,20,400,tempo.bpm)})" /></div></ScoreInfoDropdown>
      <ScoreInfoDropdown :label="qtrc('project/newscore','Measures')" :value-label="measuresLabel"><template #value><span class="value-text">{{ measuresLabel }}</span></template><label class="check"><input type="checkbox" :checked="!!info.pickup" @change="patch({pickup:($event.target as HTMLInputElement).checked ? pickup : null})" />{{ qtrc('project/newscore','Create pickup measure') }}</label><div class="indent"><span class="fraction-input" role="group" aria-label="Pickup measure duration"><input type="number" min="1" max="63" aria-label="Numerator" :value="pickup.numerator" @change="setPickup({...pickup,numerator:clamp(($event.target as HTMLInputElement).value,1,63,pickup.numerator)})" /><span aria-hidden="true">/</span><select aria-label="Denominator" :value="pickup.denominator" @change="setPickup({...pickup,denominator:Number(($event.target as HTMLSelectElement).value)})"><option v-for="d in denominators" :key="d">{{ d }}</option></select></span></div><label class="field"><span>{{ qtrc('project/newscore','Initial number of measures') }}</span><input type="number" min="1" max="9999" :value="info.measures" @change="patch({measures:clamp(($event.target as HTMLInputElement).value,1,9999,info.measures)})" /></label><p class="muted hint">{{ qtrc('project/newscore','Hint: You can also add & delete measures after you have created your score') }}</p></ScoreInfoDropdown>
    </div>
    <div class="general-info" role="group" :aria-label="qtrc('project/newscore','General score info')"><label v-for="field in [{key:'title',label:'Title',placeholder:'Untitled score'},{key:'composer',label:'Composer',placeholder:'Composer / arranger'},{key:'subtitle',label:'Subtitle'},{key:'lyricist',label:'Lyricist'},{key:'copyright',label:'Copyright'}] as const" :key="field.key" class="field" :class="{wide:field.key==='copyright'}"><span>{{ qtrc('project',field.label) }}</span><input :ref="el => { if (field.key === 'title') titleInput = el as HTMLInputElement }" type="text" :placeholder="'placeholder' in field ? qtrc('project',field.placeholder) : undefined" :value="info[field.key] ?? ''" @input="patch({[field.key]:($event.target as HTMLInputElement).value})" /></label></div>
  </div>
</template>
